<?php
declare(strict_types=1);
namespace App\Modules\Tourism\Services;
use App\Modules\Tourism\Models\TourismDestination;use RuntimeException;
final class TourismDestinationService{private TourismDestination $m;public function __construct(){$this->m=new TourismDestination();}public function all(int $t,bool $d=false):array{return $this->m->all($t,$d);}public function find(int $t,int $id):?array{return $this->m->find($t,$id);}public function findDeleted(int $t,int $id):?array{return $this->m->findDeleted($t,$id);}public function locations():array{return ['state'=>['Manipur'],'districts'=>['Bishnupur','Chandel','Churachandpur','Imphal East','Imphal West','Jiribam','Kakching','Kamjong','Kangpokpi','Noney','Pherzawl','Senapati','Tamenglong','Tengnoupal','Thoubal','Ukhrul'],'cities'=>['Imphal','Bishnupur','Chandel','Churachandpur','Jiribam','Kakching','Kamjong','Kangpokpi','Noney','Pherzawl','Senapati','Tamenglong','Moreh','Thoubal','Ukhrul']];}public function create(int $t,array $i,int $u):int{$d=$this->validate($i);if($this->m->nameExists($t,$d['name']))throw new RuntimeException('A destination with this name already exists.');$d['slug']=$this->slug($t,$this->slugify($d['name']));return $this->m->create($t,$d,$u);}public function update(int $t,int $id,array $i,int $u):void{if(!$this->find($t,$id))throw new RuntimeException('Destination not found.');$d=$this->validate($i);if($this->m->nameExists($t,$d['name'],$id))throw new RuntimeException('A destination with this name already exists.');$d['slug']=$this->slug($t,$this->slugify($d['name']),$id);$this->m->update($t,$id,$d,$u);}public function delete(int $t,int $id,int $u):void{if(!$this->find($t,$id))throw new RuntimeException('Destination not found.');$this->m->softDelete($t,$id,$u);}public function restore(int $t,int $id,int $u):void{if(!$this->findDeleted($t,$id))throw new RuntimeException('Deleted destination not found.');$this->m->restore($t,$id,$u);}private function validate(array $i):array{$d=['name'=>$this->str($i['name']??''),'description'=>$this->str($i['description']??''),'district'=>$this->str($i['district']??''),'city'=>$this->str($i['city']??''),'state'=>$this->str($i['state']??'')?:'Manipur','best_time_to_visit'=>$this->str($i['best_time_to_visit']??''),'suggested_duration'=>$this->str($i['suggested_duration']??''),'latitude'=>$this->coord($i['latitude']??null,-90,90,'Latitude'),'longitude'=>$this->coord($i['longitude']??null,-180,180,'Longitude'),'status'=>$this->str($i['status']??'Active')?:'Active'];if(!$d['name'])throw new RuntimeException('Destination name is required.');if(($d['latitude']===null)!==($d['longitude']===null))throw new RuntimeException('Latitude and longitude must be provided together.');if(!in_array($d['status'],['Active','Inactive'],true))throw new RuntimeException('Invalid status.');return $d;}private function coord(mixed $v,float $min,float $max,string $n):?string{$v=trim((string)$v);if($v==='')return null;if(!is_numeric($v)||(float)$v<$min||(float)$v>$max)throw new RuntimeException($n.' must be between '.$min.' and '.$max.'.');return number_format((float)$v,7,'.','');}private function slug(int $t,string $b,?int $ignore=null):string{$b=$b?:'destination';$c=$b;$n=2;while($this->m->slugExists($t,$c,$ignore))$c=$b.'-'.$n++;return $c;}private function slugify(string $v):string{$v=strtolower(trim($v));$v=preg_replace('/[^a-z0-9]+/','-',$v)??'';return trim($v,'-');}private function str(mixed $v):?string{$v=trim((string)$v);return $v===''?null:$v;}}
